command:
// For any world tokens selected, it will scale them to the
// right size given their UWP diameter and the grid size of
// the scene. Assumes that the grid scale is in kilometres.

let selected = canvas.tokens.controlled;

const px = canvas.scene.grid.size;
const d = canvas.scene.grid.distance;
console.log(canvas.scene.grid);

if (canvas.scene.grid.units !== "km") {
  ui.notifications.error("Scene grid units must be 'km' to be able to scale worlds");
  return;
}

if (d < 100) {
  ui.notifications.error("Grid scale of < 100km is unsuitable for scaling worlds");
  return;
}

for (let token of selected) {
  let type = token.document.actor.type;
  if (type === "world") {
    let diameter = token.document.actor.system.world.uwp.size;

    let w = parseInt((diameter * 1600) / d);
    if (w < 1) {
      w = 0.5;
    } else if (w > 50) {
      w = 50;
    }
    await token.document.update({"height": w, "width": w });
  }
}
